mapper.select:
select * from (
select distinct pcpf.SEQNO as seqno, '1' paType, pcpf.CDATE as CDATE, CONCAT(CONCAT(CONCAT(pp.PORTFOLIO_ID , '('), pp.PORTFOLIO_NAME) , ')') as portfolioId, CONCAT(CONCAT(CONCAT(sci.ACCT_NAME,'('), sci.ACCT_NO), ')') as FUNDACCOUNT,
CASE WHEN (IFNULL(ptpd.PA_BUSS_TYPE, ptfpdt.PA_BUSS_TYPE) = '22' OR IFNULL(ptpd.PA_BUSS_TYPE, ptfpdt.PA_BUSS_TYPE) = '24') and (IFNULL(trd.ps, tfpdt.ps) = 'T01' OR IFNULL(trd.ps, tfpdt.ps) = 'T02') THEN IFNULL(trd.FINPROD_TYPE2, tfpdt.FINPROD_TYPE2) ELSE IFNULL(IFNULL(PTPD.PA_BUSS_TYPE, IFNULL(PTFPDT.PA_BUSS_TYPE, IFNULL(TRD.FINPROD_TYPE2, TFPDT.FINPROD_TYPE2))), PTPD1.PA_BUSS_TYPE) END CASHFLOWTYPE, IFNULL(IFNULL(TRD.PS, TFPDT.PS), TRD1.PS) CASH_TYPE, CASE tfpdt.ps WHEN 'C11' THEN tfpdt.finprod_type2 ELSE NULL END FEETYPE, IFNULL(IFNULL(fp.FINPROD_ABBR, ftp.finprod_id),fp.FINPROD_NAME) as ASSETSIGN, ROUND(IFNULL(pcpf.AMOUNT,0)/#{displayAccuracy},2) as CASHFLOW, pcpf.CCY ccy from PTL_CASH_POSITION_FLOW pcpf left join PTL_PORTFOLIO pp on pcpf.PORTFOLIO_ID = pp.PORTFOLIO_ID left join STL_PAY_ORDERS spo on pcpf.ORDER_ID = spo.ORDER_ID left join TRD_PRODUCT_DEAL trd on spo.TRADE_ID = trd.TRADE_ID left join PA_TRD_PRODUCT_DEAL ptpd on ptpd.TRADE_ID = trd.TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL TRD1 ON TRD1.TRADE_ID = PCPF.ORDER_ID LEFT JOIN PA_TRD_PRODUCT_DEAL PTPD1 ON PTPD1.TRADE_ID = TRD1.TRADE_ID left join TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt on spo.TRADE_ID = tfpdt.TOTLE_TRADE_ID left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL ptfpdt on ptfpdt.TOTLE_TRADE_ID = tfpdt.TOTLE_TRADE_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = IFNULL(trd.FINPROD_ID,tfpdt.FINPROD_ID) left join FIN_TRADE_PRODUCT FTP on FTP.FINPROD_ID = IFNULL(trd.FINPROD_ID,tfpdt.FINPROD_ID) left join FIN_PRODUCT_ADD on fp.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join PTL_PORTFOLIO_AUTHORITY pa on pa.portfolio_id = pp.portfolio_id left join STL_CAPACCT_INFO sci on sci.ACCT_NO = pcpf.acct_id
where ( (trd.TRADE_ID is not null and trd.TRADE_STATUS = '01' AND trd.IS_CANCEL='N') or (TRD1.TRADE_ID is not null and TRD1.TRADE_STATUS = '01' AND TRD1.IS_CANCEL='N') or (tfpdt.TOTLE_TRADE_ID is not null and tfpdt.TRADE_STATUS = '01' AND tfpdt.IS_CANCEL='N') )
and (pcpf.PORTFOLIO_ID in
null) OR pcpf.PORTFOLIO_ID in (
#{item} )
AND (FIN_PRODUCT_ADD.PROD_MANAGER IN
null) OR FIN_PRODUCT_ADD.PROD_MANAGER IN (
#{item} )
and (pcpf.ACCT_ID in
null) or pcpf.ACCT_ID in (
#{item} )
AND (pcpf.CDATE BETWEEN STR_TO_DATE(#{searchDateStart},'%Y-%m-%d') AND STR_TO_DATE(#{searchDateEnd},'%Y-%m-%d'))
and pcpf.HODING_TYPE = '03' and pa.USER_ID = #{userId}
and pcpf.CCY = #{ccy,jdbcType=VARCHAR}
AND (SPO.ORDER_STATUS = #{ORDER_STATUS_01} OR SPO.ORDER_STATUS IS NULL) AND PCPF.ORDER_ID NOT IN (SELECT RTRIM(SPO1.ORDER_ID, 'R') FROM STL_PAY_ORDERS SPO1 WHERE SPO1.ORDER_STATUS = #{ORDER_STATUS_02}
AND (SPO1.SETTLE_DATE BETWEEN STR_TO_DATE(#{searchDateStart},'%Y-%m-%d') AND STR_TO_DATE(#{searchDateEnd},'%Y-%m-%d'))
and SPO1.PORTFOLIO_ID in
#{item}
)
and (( CASE WHEN ( IFNULL(ptpd.PA_BUSS_TYPE, ptfpdt.PA_BUSS_TYPE) = '22' OR IFNULL(ptpd.PA_BUSS_TYPE, ptfpdt.PA_BUSS_TYPE) = '24' ) AND ( IFNULL(trd.ps, tfpdt.ps) = 'T01' OR IFNULL(trd.ps, tfpdt.ps) = 'T02' ) THEN IFNULL(trd.FINPROD_TYPE2, tfpdt.FINPROD_TYPE2) ELSE IFNULL(IFNULL(PTPD.PA_BUSS_TYPE, IFNULL(PTFPDT.PA_BUSS_TYPE, IFNULL( TRD.FINPROD_TYPE2, TFPDT.FINPROD_TYPE2))), PTPD1.PA_BUSS_TYPE) END) in
#{item}
)
union all
select distinct '' as seqno, '0' paType, fcp.PAY_DATE as CDATE, CONCAT(CONCAT(CONCAT(pp.PORTFOLIO_ID,'('),pp.PORTFOLIO_NAME),')') as portfolioId, CONCAT(CONCAT(CONCAT(sci.ACCT_NAME,'('),sci.ACCT_NO),')') as FUNDACCOUNT,
IFNULL(ftp.FINPROD_TYPE2,fp.FINPROD_TYPE2) CASHFLOWTYPE, fcp.CASH_TYPE, NULL FEETYPE, IFNULL(IFNULL(ftp.finprod_id, fp.FINPROD_ABBR),fp.finprod_name) as ASSETSIGN, case WHEN FP.FINPROD_TYPE2 = #{F01} THEN ROUND(psp.AMOUNT*fcp.CASH_AMT/#{displayAccuracy},2) WHEN FP.FINPROD_TYPE2 = 'F16' and fcp.CASH_TYPE = '05' THEN ROUND(BPP.TDY_UNPAID_INTINCEXP,2) WHEN FP.FINPROD_TYPE2 = 'F16' and fcp.CASH_TYPE = '01' THEN ROUND(BPP1.TDY_UNPAID_INTINCEXP,2) when FTP.FINPROD_TYPE2 IN ('F02', 'F04', 'F08', 'F30') then -1 * ROUND(fcp.CASH_AMT/#{displayAccuracy},2) when FTP.FINPROD_TYPE2 IN ('F03', 'F05', 'F09', 'F29') then ROUND(fcp.CASH_AMT/#{displayAccuracy},2) else ROUND(psp.AMOUNT*fcp.CASH_AMT/IFNULL(fcp.CASH_BASEAMT,1)/#{displayAccuracy},2) end as CASHFLOW, psp.ccy from PTL_SEC_POSITION psp left join PTL_PORTFOLIO pp on psp.PORTFOLIO_ID = pp.PORTFOLIO_ID left join PTL_CAPACCT_INFO pci on psp.PORTFOLIO_ID = pci.PORTFOLIO_ID and pci.ACCT_TYPE = 'A01' and pci.ccy=psp.ccy left join STL_CAPACCT_INFO sci on pci.ACCT_NO = sci.ACCT_NO left join FIN_CASH_PLAN fcp on fcp.FINPROD_ID = psp.FINPROD_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID left join FIN_TRADE_PRODUCT FTP on FTP.FINPROD_ID = psp.FINPROD_ID left join FIN_PRODUCT_ADD on fp.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join PTL_PORTFOLIO_AUTHORITY pa on pa.portfolio_id = pp.portfolio_id left join FIN_CASH_INFO fci on fcp.FINPROD_ID = fci.FINPROD_ID and fci.cash_id = fcp.cash_id left JOIN BOK_POSITION_PRDFEE BPP ON fcp.FINPROD_ID = BPP.FINPROD_ID AND fcp.BRANCH = BPP.BRANCH AND BPP.CDATE = fcp.MDATE -1 and fci.CASH_TYPE_2 = BPP.FEE_TYPE left JOIN BOK_POSITION_PRD BPP1 ON fcp.FINPROD_ID = BPP1.FINPROD_ID AND fcp.BRANCH = BPP1.BRANCH AND BPP1.CDATE = fcp.MDATE -1 LEFT JOIN FIN_PRODUCT_ADD PRODADD ON (PSP.PORTFOLIO_ID = PRODADD.PORTFOLIO_ID or pp.PARENT_PORTFOLIO_ID = PRODADD.PORTFOLIO_ID) LEFT JOIN FIN_PRODUCT PROD ON PRODADD.FINPROD_ID = PROD.FINPROD_ID where PROD.VDATE <= FCP.VDATE
and psp.PORTFOLIO_ID in
#{item}
and pci.ACCT_NO in
#{item}
AND FIN_PRODUCT_ADD.PROD_MANAGER IN
#{item}
AND (fcp.PAY_DATE BETWEEN STR_TO_DATE(#{searchDateStart},'%Y-%m-%d') AND STR_TO_DATE(#{searchDateEnd},'%Y-%m-%d'))
and not exists ( select 1 from TRD_PRODUCT_DEAL tpd where tpd.CASH_ID = fcp.CASH_ID and TPD.MDATE >= FCP.VDATE AND FCP.MDATE >= TPD.MDATE and tpd.TRADE_STATUS = #{TRADE_STATUS_01, jdbcType=VARCHAR} AND TPD.IS_CANCEL='N'
)
and ((fcp.MDATE = STR_TO_DATE(#{sysDate},'%Y-%m-%d') AND psp.CDATE = STR_TO_DATE(#{sysDate},'%Y-%m-%d') - 1) OR (fcp.MDATE != STR_TO_DATE(#{sysDate},'%Y-%m-%d') AND psp.CDATE = STR_TO_DATE(#{sysDate},'%Y-%m-%d'))) and (fp.IS_RIGHT = 'N' or fp.IS_RIGHT is null) and pa.USER_ID = #{userId}
and (fp.CCY = #{ccy,jdbcType=VARCHAR} or FTP.CCY = #{ccy,jdbcType=VARCHAR})
and fp.FINPROD_TYPE2 in
#{item}
and psp.AMOUNT > 0 union all
select distinct '' as seqno, '0' paType, fcp.PAY_DATE as CDATE, CONCAT(CONCAT(CONCAT(pp.PORTFOLIO_ID ,'('),pp.PORTFOLIO_NAME),')') as portfolioId, CONCAT(CONCAT(CONCAT(sci.ACCT_NAME,'('),sci.ACCT_NO),')') as FUNDACCOUNT,
fp.FINPROD_TYPE2 as CASHFLOWTYPE, fcp.CASH_TYPE, NULL FEETYPE, IFNULL(fp.FINPROD_ABBR,fp.finprod_name) as ASSETSIGN, ROUND(psp.AMOUNT*fcp.CASH_AMT/#{displayAccuracy},2) CASHFLOW, fp.ccy from PTL_SEC_POSITION psp left join PTL_PORTFOLIO pp on psp.PORTFOLIO_ID = pp.PORTFOLIO_ID left join PTL_CAPACCT_INFO pci on psp.PORTFOLIO_ID = pci.PORTFOLIO_ID and pci.ACCT_TYPE = 'A01' and pci.ccy=psp.ccy left join STL_CAPACCT_INFO sci on pci.ACCT_NO = sci.ACCT_NO left join FIN_CASH_PLAN fcp on fcp.FINPROD_ID = psp.FINPROD_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID left join FIN_PRODUCT_ADD on fp.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join PTL_PORTFOLIO_AUTHORITY pa on pa.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT_ADD PRODADD ON (PSP.PORTFOLIO_ID = PRODADD.PORTFOLIO_ID or pp.PARENT_PORTFOLIO_ID = PRODADD.PORTFOLIO_ID) LEFT JOIN FIN_PRODUCT PROD ON PRODADD.FINPROD_ID = PROD.FINPROD_ID where PROD.VDATE <= FCP.VDATE
and psp.PORTFOLIO_ID in
#{item}
and pci.ACCT_NO in
#{item}
AND FIN_PRODUCT_ADD.PROD_MANAGER IN
#{item}
AND (fcp.PAY_DATE BETWEEN STR_TO_DATE(#{searchDateStart},'%Y-%m-%d') AND STR_TO_DATE(#{searchDateEnd},'%Y-%m-%d'))
and fp.FINPROD_TYPE2 in
#{item}
and not exists ( select 1 from TRD_PRODUCT_DEAL tpd where tpd.CASH_ID = fcp.CASH_ID and tpd.MDATE >= fcp.VDATE and fcp.MDATE >= tpd.MDATE and tpd.TRADE_STATUS = #{TRADE_STATUS_01, jdbcType=VARCHAR} AND TPD.IS_CANCEL='N' )
and ((fcp.MDATE = STR_TO_DATE(#{sysDate},'%Y-%m-%d') AND psp.CDATE = STR_TO_DATE(#{sysDate},'%Y-%m-%d') - 1) OR (fcp.MDATE != STR_TO_DATE(#{sysDate},'%Y-%m-%d') AND psp.CDATE = STR_TO_DATE(#{sysDate},'%Y-%m-%d'))) and fp.IS_RIGHT = 'Y' and ( NOT EXISTS ( select 1 from FIN_EXERCISE_PLAN fep where fep.EXERCISE_DATE >= STR_TO_DATE(#{sysDate},'%Y-%m-%d') AND fep.FINPROD_ID = FCP.FINPROD_ID ) or NOT EXISTS ( select 1 from FIN_EXERCISE_PLAN fep where fep.EXERCISE_DATE >= STR_TO_DATE(#{sysDate},'%Y-%m-%d') AND fep.FINPROD_ID = FCP.FINPROD_ID AND fcp.PAY_DATE > fep.EXERCISE_DATE ) )
and fp.CCY = #{ccy,jdbcType=VARCHAR}
and psp.AMOUNT > 0 and pa.USER_ID = #{userId}
union all
select distinct '' as seqno, '0' paType, fep1.EXERCISE_DATE as CDATE, CONCAT(CONCAT(CONCAT(pp.PORTFOLIO_ID,'('), pp.PORTFOLIO_NAME),')') as portfolioId, CONCAT(CONCAT(CONCAT(sci.ACCT_NAME ,'('),sci.ACCT_NO),')') as FUNDACCOUNT,
fp.FINPROD_TYPE2 as CASHFLOWTYPE, '行权' CASH_TYPE, NULL FEETYPE, IFNULL(fp.FINPROD_ABBR,fp.finprod_name) as ASSETSIGN, psp.AMOUNT*fep1.EXERCISE_PRICE CASHFLOW, fp.ccy ccy from PTL_SEC_POSITION psp left join PTL_PORTFOLIO pp on psp.PORTFOLIO_ID = pp.PORTFOLIO_ID left join PTL_PORTFOLIO_AUTHORITY pa on pa.portfolio_id = pp.portfolio_id left join PTL_CAPACCT_INFO pci on psp.PORTFOLIO_ID = pci.PORTFOLIO_ID and pci.ACCT_TYPE = 'A01' and pci.ccy=psp.ccy left join STL_CAPACCT_INFO sci on pci.ACCT_NO = sci.ACCT_NO left join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID left join FIN_PRODUCT_ADD on fp.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join FIN_EXERCISE_PLAN fep1 on fep1.FINPROD_ID = psp.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON (PSP.PORTFOLIO_ID = PRODADD.PORTFOLIO_ID or pp.PARENT_PORTFOLIO_ID = PRODADD.PORTFOLIO_ID) LEFT JOIN FIN_PRODUCT PROD ON PRODADD.FINPROD_ID = PROD.FINPROD_ID
PROD.VDATE <= fep1.VDATE AND psp.AMOUNT > 0 AND NOT EXISTS (SELECT 1 FROM FIN_EXERCISE_PLAN FEP WHERE FEP.CASH_ID = FEP1.CASH_ID AND FEP.EXERCISE_DATE < FEP1.EXERCISE_DATE AND FEP.FINPROD_ID = FEP1.FINPROD_ID)
and psp.PORTFOLIO_ID in
#{item}
#{item}
AND FIN_PRODUCT_ADD.PROD_MANAGER IN
#{item}
AND (fep1.EXERCISE_DATE BETWEEN STR_TO_DATE(#{searchDateStart},'%Y-%m-%d') AND STR_TO_DATE(#{searchDateEnd},'%Y-%m-%d'))
and fp.FINPROD_TYPE2 in
#{item}
and not exists ( select 1 from TRD_PRODUCT_DEAL tpd where tpd.PS in(#{T03},#{T39}) and tpd.SETTLE_DATE = fep1.EXERCISE_DATE AND TPD.FINPROD_ID = PSP.FINPROD_ID and tpd.TRADE_STATUS = '01' AND TPD.IS_CANCEL='N' ) and PSP.CDATE = STR_TO_DATE(#{sysDate},'%Y-%m-%d') and fp.IS_RIGHT = 'Y' and fep1.EXERCISE_DATE is not null and pa.USER_ID = #{userId}
and fp.CCY = #{ccy,jdbcType=VARCHAR}
) total ORDER BY CDATE, portfolioId, CASHFLOWTYPE

select '日期' as aggregDimension, total.portfolioId as portfolioId, total.ccy as ccy, total.fundAccount as fundAccount, round(sum(total.INCASHFLOW)/#{displayAccuracy1},2) as inCashFlow, round(sum(total.OUTCASHFLOW) / #{displayAccuracy1},2) as outCashFlow, round(sum(total.NETCASHFLOW) /#{displayAccuracy1},2) as netCashFlow from (
select DISTINCT pcpf.SEQNO as seqno, pcpf.CDATE as CDATE, CONCAT(CONCAT(CONCAT(pcpf.PORTFOLIO_ID,'('),pp.PORTFOLIO_NAME), ')') as portfolioId, pcpf.CCY ccy, CONCAT(CONCAT(CONCAT(sci.ACCT_NAME,'('),sci.ACCT_NO), ')') as fundAccount, case when pcpf.AMOUNT > 0 then IFNULL(pcpf.AMOUNT,0) else 0 end as INCASHFLOW , case when pcpf.AMOUNT < 0 then IFNULL(pcpf.AMOUNT,0) else 0 end as OUTCASHFLOW , IFNULL(pcpf.AMOUNT,0)as NETCASHFLOW from PTL_CASH_POSITION_FLOW pcpf left join PTL_PORTFOLIO pp on pcpf.PORTFOLIO_ID = pp.PORTFOLIO_ID left join FIN_PRODUCT on pcpf.PORTFOLIO_ID = FIN_PRODUCT.FINPROD_MARKET_ID left join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join STL_PAY_ORDERS spo on pcpf.ORDER_ID = spo.ORDER_ID left join TRD_PRODUCT_DEAL trd on spo.TRADE_ID = trd.TRADE_ID left join TRD_PRODUCT_DEAL trd1 on pcpf.ORDER_ID = trd1.TRADE_ID left join TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt on spo.TRADE_ID = tfpdt.TOTLE_TRADE_ID left join STL_CAPACCT_INFO sci on sci.ACCT_NO = pcpf.ACCT_ID left join PTL_PORTFOLIO_AUTHORITY pa on pa.portfolio_id = pp.portfolio_id where ( (trd.TRADE_ID is not null and trd.TRADE_STATUS = '01' AND trd.IS_CANCEL='N') or (TRD1.TRADE_ID is not null and TRD1.TRADE_STATUS = '01' AND TRD1.IS_CANCEL='N') or (tfpdt.TOTLE_TRADE_ID is not null and tfpdt.TRADE_STATUS = '01' AND tfpdt.IS_CANCEL='N') )
and (pcpf.PORTFOLIO_ID in
null) OR pcpf.PORTFOLIO_ID in (
#{item} )
and pcpf.ACCT_ID = #{fundAccount1}
AND (pcpf.CDATE BETWEEN STR_TO_DATE(#{searchDateStart1},'%Y-%m-%d') AND STR_TO_DATE(#{searchDateEnd1},'%Y-%m-%d'))
AND FIN_PRODUCT_ADD.PROD_MANAGER IN
#{item}
and pcpf.HODING_TYPE = '03' and pcpf.CCY = #{ccy1,jdbcType=VARCHAR} and pa.USER_ID = #{userId} AND (SPO.ORDER_STATUS = #{ORDER_STATUS_01} OR SPO.ORDER_STATUS IS NULL) AND PCPF.ORDER_ID NOT IN (SELECT RTRIM(SPO1.ORDER_ID, 'R') FROM STL_PAY_ORDERS SPO1 WHERE SPO1.ORDER_STATUS = #{ORDER_STATUS_02}
AND (SPO1.SETTLE_DATE BETWEEN STR_TO_DATE(#{searchDateStart1},'%Y-%m-%d') AND STR_TO_DATE(#{searchDateEnd1},'%Y-%m-%d'))
and SPO1.PORTFOLIO_ID in
#{item}
) union all
select DISTINCT '' as seqno, fcp.PAY_DATE as CDATE, CONCAT(CONCAT(CONCAT(pp.PORTFOLIO_ID ,'('),pp.PORTFOLIO_NAME),')') as portfolioId, fp.ccy CCY, CONCAT(CONCAT(CONCAT(sci.ACCT_NAME, '('),sci.ACCT_NO),')') as fundAccount, case when fp.FINPROD_TYPE2 = 'F02' and -1*psp.AMOUNT*fcp.CASH_AMT < 0 then -1 * ROUND(psp.AMOUNT*fcp.CASH_AMT/IFNULL(fcp.CASH_BASEAMT,1),2) when fp.FINPROD_TYPE2 != 'F02' and psp.AMOUNT*fcp.CASH_AMT > 0 then ROUND(psp.AMOUNT*fcp.CASH_AMT/IFNULL(fcp.CASH_BASEAMT,1),2) else 0 end as INCASHFLOW, case when fp.FINPROD_TYPE2 = 'F02' and psp.AMOUNT*fcp.CASH_AMT > 0 then -1 * ROUND(psp.AMOUNT*fcp.CASH_AMT/IFNULL(fcp.CASH_BASEAMT,1),2) when fp.FINPROD_TYPE2 != 'F02' and psp.AMOUNT*fcp.CASH_AMT < 0 then ROUND(psp.AMOUNT*fcp.CASH_AMT/IFNULL(fcp.CASH_BASEAMT,1),2) else 0 end as OUTCASHFLOW, case when fp.FINPROD_TYPE2 != 'F02' then -1 * ROUND(psp.AMOUNT*fcp.CASH_AMT/IFNULL(fcp.CASH_BASEAMT,1),2) else ROUND(psp.AMOUNT*fcp.CASH_AMT/IFNULL(fcp.CASH_BASEAMT,1),2) end as NETCASHFLOW
from PTL_SEC_POSITION psp left join PTL_PORTFOLIO pp on psp.PORTFOLIO_ID = pp.PORTFOLIO_ID left join PTL_CAPACCT_INFO pci on psp.PORTFOLIO_ID = pci.PORTFOLIO_ID and pci.ACCT_TYPE = 'A01' and pci.ccy=psp.ccy left join FIN_CASH_PLAN fcp on fcp.FINPROD_ID = psp.FINPROD_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID left join FIN_PRODUCT_ADD on fp.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join STL_CAPACCT_INFO sci on sci.ACCT_NO = pci.ACCT_NO left join PTL_PORTFOLIO_AUTHORITY pa on pa.portfolio_id = pp.portfolio_id
where 1 = 1
and psp.PORTFOLIO_ID in
#{item}
AND FIN_PRODUCT_ADD.PROD_MANAGER IN
#{item}
and pci.ACCT_NO = #{fundAccount1}
AND (fcp.PAY_DATE BETWEEN STR_TO_DATE(#{searchDateStart1},'%Y-%m-%d') AND STR_TO_DATE(#{searchDateEnd1},'%Y-%m-%d'))
and not exists ( select 1 from TRD_PRODUCT_DEAL tpd where tpd.CASH_ID = fcp.CASH_ID and tpd.MDATE > FCP.VDATE AND FCP.MDATE >= TPD.MDATE and tpd.TRADE_STATUS = #{TRADE_STATUS_01, jdbcType=VARCHAR} AND TPD.IS_CANCEL='N' ) and psp.CDATE = STR_TO_DATE(#{sysDate},'%Y-%m-%d') and (fp.IS_RIGHT = 'N' or fp.IS_RIGHT is null) and fp.CCY = #{ccy1,jdbcType=VARCHAR} and pa.USER_ID = #{userId} union all
select DISTINCT '' as seqno, fcp.PAY_DATE as CDATE, CONCAT(CONCAT(CONCAT(pp.PORTFOLIO_ID,'('),pp.PORTFOLIO_NAME),')') as portfolioId, fp.ccy CCY, CONCAT(CONCAT(CONCAT(sci.ACCT_NAME,'('), sci.ACCT_NO), ')') as fundAccount, case when psp.AMOUNT*fcp.CASH_AMT > 0 then ROUND(psp.AMOUNT*fcp.CASH_AMT/IFNULL(fcp.CASH_BASEAMT,1),2) else 0 end as INCASHFLOW, case when psp.AMOUNT*fcp.CASH_AMT < 0 then ROUND(psp.AMOUNT*fcp.CASH_AMT/IFNULL(fcp.CASH_BASEAMT,1),2) else 0 end as OUTCASHFLOW, ROUND(psp.AMOUNT*fcp.CASH_AMT/IFNULL(fcp.CASH_BASEAMT,1),2) as NETCASHFLOW
from PTL_SEC_POSITION psp left join PTL_PORTFOLIO pp on psp.PORTFOLIO_ID = pp.PORTFOLIO_ID left join PTL_CAPACCT_INFO pci on psp.PORTFOLIO_ID = pci.PORTFOLIO_ID and pci.ACCT_TYPE = 'A01' and pci.ccy=psp.ccy left join FIN_CASH_PLAN fcp on fcp.FINPROD_ID = psp.FINPROD_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID left join FIN_PRODUCT_ADD on fp.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join STL_CAPACCT_INFO sci on sci.ACCT_NO = pci.ACCT_NO left join PTL_PORTFOLIO_AUTHORITY pa on pa.portfolio_id = pp.portfolio_id
where 1 = 1
and psp.PORTFOLIO_ID in
#{item}
and pci.ACCT_NO = #{fundAccount1}
AND FIN_PRODUCT_ADD.PROD_MANAGER IN
#{item}
AND (fcp.PAY_DATE BETWEEN STR_TO_DATE(#{searchDateStart1},'%Y-%m-%d') AND STR_TO_DATE(#{searchDateEnd1},'%Y-%m-%d'))
and not exists ( select 1 from TRD_PRODUCT_DEAL tpd where tpd.CASH_ID = fcp.CASH_ID and tpd.MDATE > FCP.VDATE AND FCP.MDATE >= TPD.MDATE and tpd.TRADE_STATUS = #{TRADE_STATUS_01, jdbcType=VARCHAR} AND TPD.IS_CANCEL='N' ) and psp.CDATE = STR_TO_DATE(#{sysDate},'%Y-%m-%d') and fp.IS_RIGHT = 'Y' and ( ( select min(fep.EXERCISE_DATE) from FIN_EXERCISE_PLAN fep where 1 = 1 and fep.EXERCISE_DATE >= STR_TO_DATE(#{sysDate},'%Y-%m-%d') ) is null or fcp.PAY_DATE < ( select min(fep.EXERCISE_DATE) from FIN_EXERCISE_PLAN fep where 1 = 1 and fep.EXERCISE_DATE >= STR_TO_DATE(#{sysDate},'%Y-%m-%d') ) ) and fp.CCY = #{ccy1,jdbcType=VARCHAR} and pa.USER_ID = #{userId} union all
select DISTINCT '' as seqno, fep1.EXERCISE_DATE as CDATE, CONCAT(CONCAT(CONCAT(pp.PORTFOLIO_ID ,'(') , pp.PORTFOLIO_NAME ), ')') as portfolioId, fp.ccy CCY, CONCAT(CONCAT(CONCAT(sci.ACCT_NAME , '(') , sci.ACCT_NO) , ')') as fundAccount, case when psp.AMOUNT*fep1.EXERCISE_PRICE > 0 then ROUND(psp.AMOUNT*fep1.EXERCISE_PRICE/100,2) else 0 end as INCASHFLOW, case when psp.AMOUNT*fep1.EXERCISE_PRICE < 0 then ROUND(psp.AMOUNT*fep1.EXERCISE_PRICE/100,2) else 0 end as OUTCASHFLOW, ROUND(psp.AMOUNT*fep1.EXERCISE_PRICE/100,2) as NETCASHFLOW from PTL_SEC_POSITION psp left join PTL_PORTFOLIO pp on psp.PORTFOLIO_ID = pp.PORTFOLIO_ID left join PTL_PORTFOLIO_AUTHORITY pa on pa.portfolio_id = pp.portfolio_id left join PTL_CAPACCT_INFO pci on psp.PORTFOLIO_ID = pci.PORTFOLIO_ID and pci.ACCT_TYPE = 'A01' and pci.ccy=psp.ccy left join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID left join FIN_PRODUCT_ADD on fp.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join (select fep.FINPROD_ID,fep.EXERCISE_DATE,fep.EXERCISE_PRICE from FIN_EXERCISE_PLAN fep where fep.EXERCISE_DATE = ( select min(fep.EXERCISE_DATE) from FIN_EXERCISE_PLAN fep where 1 = 1 and fep.EXERCISE_DATE >= STR_TO_DATE(#{sysDate},'%Y-%m-%d') ) ) fep1 on fep1.FINPROD_ID = psp.FINPROD_ID left join STL_CAPACCT_INFO sci on sci.ACCT_NO = pci.ACCT_NO where 1 = 1
and psp.PORTFOLIO_ID in
#{item}
and pci.ACCT_NO = #{fundAccount1}
AND (fep1.EXERCISE_DATE BETWEEN STR_TO_DATE(#{searchDateStart1},'%Y-%m-%d') AND STR_TO_DATE(#{searchDateEnd1},'%Y-%m-%d'))
AND FIN_PRODUCT_ADD.PROD_MANAGER IN
#{item}
and not exists ( select 1 from TRD_PRODUCT_DEAL tpd where 1 = 1 and tpd.PS in('01','02') and tpd.SETTLE_DATE = fep1.EXERCISE_DATE and tpd.TRADE_STATUS = '01' AND TPD.IS_CANCEL='N' ) and PSP.CDATE = STR_TO_DATE(#{sysDate},'%Y-%m-%d') and fp.IS_RIGHT = 'Y' and fep1.EXERCISE_DATE is not null and fp.CCY = #{ccy1,jdbcType=VARCHAR} and pa.USER_ID = #{userId} ) total group by total.ccy,total.portfolioId,total.fundAccount
